let __v_305 = { let __dict_306 = Value::dict(); let __v_307 = Value::from("potato"); let __v_308 = Value::from("Lift new potatoes in June and July, once the flowers open, and maincrops in September and October when the tops have died back. Fork well beside the row so you do not spear them, then leave them on the soil for an hour to dry before storing in paper sacks in the dark."); __dict_306.dict_set(__v_307, __v_308)?; let __v_309 = Value::from("carrot"); let __v_310 = Value::from("Pull carrots from June, thinning as you go, and lift the main crop in October before the first hard frost. They are ready when the shoulder is 2cm across. Twist the tops off before storing, because leaves keep drawing water, and keep them in damp sand in a cool shed."); __dict_306.dict_set(__v_309, __v_310)?; let __v_311 = Value::from("onion"); let __v_312 = Value::from("Lift onions in July and August when the tops fall over and start to yellow: bend the tops down, leave them a fortnight on the soil in dry weather, then store in nets somewhere airy. An onion that is not properly dried is the one that rots and takes the rest of the sack with it."); __dict_306.dict_set(__v_311, __v_312)?; let __v_313 = Value::from("lettuce"); let __v_314 = Value::from("Cut lettuce about eight to twelve weeks after sowing, in the morning when it is cold and crisp, at the base with a knife, and it will often come again. A lettuce that has started to shoot up a stem has bolted: pick it at once and eat it that day, because it turns bitter."); __dict_306.dict_set(__v_313, __v_314)?; let __v_315 = Value::from("pea"); let __v_316 = Value::from("Pick peas from June, when the pods are full but still bright green and snap cleanly, and go along the row every two or three days. Leaving them on the plant stops it flowering, and a pod left too long goes starchy and tough."); __dict_306.dict_set(__v_315, __v_316)?; let __v_317 = Value::from("bean"); let __v_318 = frame.load(rt, "_bean_harvest")?; __dict_306.dict_set(__v_317, __v_318)?; let __v_319 = Value::from("beetroot"); let __v_320 = Value::from("Beetroot is ready eight to ten weeks after sowing, at golf-ball size for eating fresh and up to tennis-ball size for storing. Twist the leaves off rather than cutting, so it does not bleed, and lift them before the first hard frost."); __dict_306.dict_set(__v_319, __v_320)?; let __v_321 = Value::from("parsnip"); let __v_322 = Value::from("Lift parsnips from October through to February, and leave them in the ground until after a frost: the cold turns starch to sugar and they taste far better. Fork underneath the root rather than pulling, because a parsnip snaps at the shoulder and the best part stays in the soil."); __dict_306.dict_set(__v_321, __v_322)?; let __v_323 = Value::from("leek"); let __v_324 = Value::from("Leeks can be lifted from September and stand in the ground all winter, which is the point of them: dig as you need them, and they will take hard frost. Earth up the stems a few weeks before lifting if you want more white."); __dict_306.dict_set(__v_323, __v_324)?; let __v_325 = Value::from("cabbage"); let __v_326 = frame.load(rt, "_brassica_harvest")?; __dict_306.dict_set(__v_325, __v_326)?; let __v_327 = Value::from("courgette"); let __v_328 = frame.load(rt, "_courgette_harvest")?; __dict_306.dict_set(__v_327, __v_328)?; let __v_329 = Value::from("radish"); let __v_330 = Value::from("Radishes are ready about four weeks after sowing, at marble size: pull one to check rather than waiting for the row. Left longer they go woody and hot, so sow little and often instead of one big row."); __dict_306.dict_set(__v_329, __v_330)?; let __v_331 = Value::from("swede"); let __v_332 = Value::from("Swedes are lifted from October, and are better after a frost, which sweetens them the way it does parsnips; they will stand in the ground into winter. Turnips are quick - six to eight weeks - and are best pulled small, at 5 to 7cm across."); __dict_306.dict_set(__v_331, __v_332)?; __dict_306 };
frame.store("HARVEST", __v_305.clone())?;
let __v_333 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"garlic\"]},\"Lift garlic in July, when the bottom three leaves have yellowed and the rest are still green: stop watering a fortnight before, ease each bulb out with a fork, and dry them somewhere airy for two or three weeks before storing. Left in longer the bulbs split and they keep badly.\"]},{\"$tuple\":[{\"$tuple\":[\"tomato\",\"tomatoes\"]},\"Pick tomatoes from late July as they turn fully red, and take the whole truss in October before the first frost. Green ones left then will ripen on a windowsill next to a banana. A tomato is ready when it gives slightly in the hand and smells of tomato.\"]},{\"$tuple\":[{\"$tuple\":[\"apple\",\"apples\"]},\"Apples are ready from August for the earlies and October for the keepers: cup one and twist - ripe fruit comes away with the stalk on and the pips inside are brown. Pick in dry weather, use the windfalls first, and store only perfect fruit, in a cool dark place, not touching.\"]},{\"$tuple\":[{\"$tuple\":[\"pear\",\"pears\"]},\"Pick pears before they are ripe, from late August, while the flesh is still hard: lift one and twist, and when the stalk parts easily it is ready to finish indoors. A pear left to soften on the tree goes gritty and rotten at the core.\"]},{\"$tuple\":[{\"$tuple\":[\"plum\",\"plums\",\"damson\",\"damsons\"]},\"Plums are ready from August, when they colour up and give a little at the stalk end: pick with the stalk on and eat the soft ones first. A plum that comes away at a squeeze is over ripe, and the wasps find those the same day you do.\"]},{\"$tuple\":[{\"$tuple\":[\"strawberry\",\"strawberries\"]},\"Pick strawberries from June, when they are red all over including the tip, and pick with a short stalk in the cool of the morning. A berry that is pale at the tip will not sweeten after picking, and one left to rot takes the rest with it.\"]},{\"$tuple\":[{\"$tuple\":[\"raspberry\",\"raspberries\"]},\"Raspberries ripen from July: pick when the berry comes away from its core with no tug, and eat or freeze them the same day, because they keep a day at most. Autumn kinds crop on into October.\"]},{\"$tuple\":[{\"$tuple\":[\"rhubarb\"]},\"Pull rhubarb from April to the end of June, twisting each stalk out and leaving three on every crown, then stop: the plant needs the rest of the year to build up for next spring. Do not pull any in the first year after planting, and never eat the leaves.\"]},{\"$tuple\":[{\"$tuple\":[\"sweetcorn\",\"sweet corn\",\"corn\",\"corn on the cob\"]},\"Sweetcorn is ready in August and September: peel back a little husk and press a kernel with a fingernail - milky juice means ready, clear means wait, doughy means it has gone over. Cook it within the hour, because the sugar turns to starch fast.\"]},{\"$tuple\":[{\"$tuple\":[\"chilli\",\"chillies\",\"chili\",\"chilies\"]},\"Chillies are ready from late summer: pick green for a milder heat, or leave them on to turn red for the fullest flavour. Cut them with a short stalk and keep picking, because a plant left to ripen stops setting new fruit.\"]},{\"$tuple\":[{\"$tuple\":[\"pumpkin\",\"pumpkins\",\"squash\",\"squashes\"]},\"Pumpkins and squash are ready in September or October, when the skin has hardened so a fingernail will not mark it and the stalk has gone corky: cut with a long handle, cure them in the sun for a week, and they keep for months somewhere dry.\"]}]}")?;
