let __v_424 = pyrt::literals::decode("{\"$dict\":[[\"spring\",\"Spring is when the plot fills up: potatoes, carrots, onions, lettuce, peas, leeks and radish from March, beetroot and beans in April, and courgettes, sweetcorn and squash once the frost has gone in May. Sow a short row every few weeks rather than one big sowing.\"],[\"summer\",\"In summer you are sowing for autumn and winter: more lettuce, radish and beetroot every three weeks, runner and french beans and courgettes until the end of June, then spring cabbage, kale and winter salad from July. Water in the morning and mulch, because this is when everything bolts.\"],[\"autumn\",\"Autumn is the sowing for next year: plant garlic, overwintering broad beans and onion sets, and sow winter salad and land cress under cover. Clear the spent crops into the compost and mulch the empty beds, because this is the season that decides next spring.\"],[\"winter\",\"Almost nothing goes in outdoors: garlic and broad beans in a mild spell, and everything else indoors. Sow tomatoes and chillies under cover from late winter, chit early potatoes on a windowsill after Christmas, and order the seed you want for the year.\"]]}")?;
