frame.store("_sow_month", { let __signature_435 = Signature { name: "_sow_month".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_437 = Value::dict(); __attrs_437.dict_set(Value::from("__doc__"), Value::from("What goes in the ground in the month the line names, or in the month it is now.\n\n    Nothing comes back for a line that names no month and no \"now\": a season or a question about\n    the plot in general is somebody else's answer.\n    "))?; __attrs_437.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_438 = Value::dict(); __attrs_437.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_434 = Frame::module(frame.globals.clone()); let mut __function_436 = NativeFunction::qualified_with_origin("_sow_month".into(), "_sow_month".into(), "bot.knowledge.garden".into(), __attrs_437, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/garden.py", first: 701, last: 726, qualname: "_sow_month" }, closure: __closure_434.clone(), freevars: vec![] }, move |rt, args| __py_20::_sow_month(rt, __closure_434.clone(), &__signature_435, args)); __function_436 })?;
let __v_439 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"potato\",\"potatoes\",\"spuds\"]},\"Plant seed potatoes from late March to mid-April, once the soil is workable and no hard frost is forecast: 30cm apart in rows 60cm apart, 10cm deep, with the sprouts pointing up. Chit them on a windowsill first, in egg boxes, for six weeks. Earlies go in first, maincrops by mid-April, and a frost on the young shoots is what sets them back.\"]},{\"$tuple\":[{\"$tuple\":[\"carrot\",\"carrots\"]},\"Sow carrots from late March to July, a few seeds every three weeks rather than one big sowing, 1cm deep and 5cm apart once thinned. They want a light, stone-free soil: stones make them fork. Cover the row with fleece or a mesh barrier, because carrot fly finds them by smell and a barrier is what actually stops it.\"]},{\"$tuple\":[{\"$tuple\":[\"onion\",\"onions\",\"shallot\",\"shallots\",\"onion sets\"]},\"Plant onion sets from mid-March to mid-April, pushing them into firm soil so just the tip shows, 10cm apart with 30cm between rows. Birds pull them out, so a few short sticks or netting over the row saves them. Onions want firm ground: tread the bed before planting, not after, and keep it weeded.\"]},{\"$tuple\":[{\"$tuple\":[\"lettuce\",\"lettuces\",\"salad leaves\",\"rocket\",\"spinach\"]},\"Sow lettuce and salad leaves from March to August, a small pinch every two or three weeks for a steady supply, 1cm deep and 20cm apart for hearting kinds. They bolt in heat: water in the morning, shade the row in a hot spell, and pick leaves young. Cut-and-come-again salad is the easiest thing to grow in a pot.\"]},{\"$tuple\":[{\"$tuple\":[\"pea\",\"peas\",\"mangetout\",\"sugar snap\"]},\"Sow peas from March to early June, 5cm deep in a wide flat trench rather than a single line, 8cm apart, with a net or twiggy sticks up for them to climb. Mice take the seed, so start them in a gutter of compost if a row disappears. Pick pods every couple of days or the plants stop producing.\"]},{\"$tuple\":[{\"$tuple\":[\"bean\",\"beans\",\"runner beans\",\"broad beans\",\"french beans\"]},\"Sow runner and french beans from late April to June, once the soil has warmed, 5cm deep and 20cm apart, after the last frost. Broad beans go in earlier, from February to April, in a double row. Beans need a frame or cane wigwam from the start, and water at the base when they flower or the flowers drop.\"]},{\"$tuple\":[{\"$tuple\":[\"beetroot\",\"beets\",\"beet\"]},\"Sow beetroot from April to July, 2cm deep and 10cm apart, thinning to one plant per station because each seed cluster holds several. Water regularly: beetroot that dries out goes woody. You can start in April under cloche and sow again in June for small roots into autumn.\"]},{\"$tuple\":[{\"$tuple\":[\"parsnip\",\"parsnips\"]},\"Sow parsnips from late February to April, and only fresh seed: parsnip seed dies in a year, which is why a saved packet comes up empty. Sow 1cm deep, 15cm apart once thinned, on ground that has not been manured or they fork. They take three weeks to show, so mark the row.\"]},{\"$tuple\":[{\"$tuple\":[\"leek\",\"leeks\",\"spring onion\",\"spring onions\"]},\"Sow leeks from March to April in a seedbed, then move them to their final spot in June at 20cm apart, dropping each one into a dibbed hole and watering it in rather than filling the hole with soil. Spring onions can be sown from March to July, a pinch every three weeks, and eaten small.\"]},{\"$tuple\":[{\"$tuple\":[\"cabbage\",\"cabbages\",\"broccoli\",\"sprouts\",\"sprout\",\"kale\",\"cauliflower\"]},\"Sow cabbage, kale and sprouts from March to May for a winter and spring crop, 1cm deep in a seedbed, then plant out 45cm apart once they have five or six leaves. Firm the soil hard around the stem. Net them straight away: pigeons strip a young brassica in a day, and cabbage white butterflies come later.\"]},{\"$tuple\":[{\"$tuple\":[\"courgette\",\"courgettes\",\"zucchini\",\"squash\",\"pumpkin\",\"pumpkins\"]},\"Sow courgettes from late April indoors and plant out in late May or June, once nights are above 10C, 90cm apart: one plant feeds a family. They need sun, rich soil and steady water. Pick them small, at 10-15cm, because a marrow-sized courgette stops the plant producing.\"]},{\"$tuple\":[{\"$tuple\":[\"radish\",\"radishes\"]},\"Sow radishes from March to September, a pinch every two weeks, 1cm deep and 2cm apart after thinning, and they are ready in about four weeks. They are the fastest thing in the veg patch and a good one to sow with children. Dry soil makes them hot and woody, so water them.\"]},{\"$tuple\":[{\"$tuple\":[\"swede\",\"swedes\",\"turnip\",\"turnips\"]},\"Sow swede in May to June and turnips from March to August, 1cm deep and 15cm apart once thinned; swede needs the whole summer to swell and is best lifted after the first frost. Club root is the risk in acid soil, so lime the bed the winter before if you have had it.\"]},{\"$tuple\":[{\"$tuple\":[\"chilli\",\"chillies\",\"chillis\",\"chilli pepper\",\"chilli peppers\",\"hot pepper\",\"hot peppers\",\"jalapeno\",\"jalapenos\",\"scotch bonnet\"]},\"Sow chillies indoors in February or March, half a centimetre deep, at 21C or more: cold seed does not come up at all, so a warm windowsill or a propagator is the whole trick. Pot them on as the roots fill the pot, pinch the top out at about 15cm to make a bush, and move them to the sunniest spot in June. Water when the top of the compost is dry and feed weekly with tomato feed once the flowers open; pick green for a milder chilli, or leave them to turn red.\"]},{\"$tuple\":[{\"$tuple\":[\"pepper\",\"peppers\",\"sweet pepper\",\"sweet peppers\",\"bell pepper\",\"bell peppers\",\"pepper plant\",\"pepper plants\"]},\"Sweet peppers want warmth and a long season: sow indoors in late February or March, half a centimetre deep, at 20C or more, and pot them on twice before planting out in June in the sunniest, most sheltered spot you have. Water regularly, because a plant that dries out drops its flowers, and feed weekly with tomato feed when the first fruit set. Pick them green, or wait for red, which is sweeter.\"]},{\"$tuple\":[{\"$tuple\":[\"basil\",\"basil seed\",\"basil seeds\",\"basil plant\",\"basil plants\"]},\"Sow basil indoors from late April to June, half a centimetre deep and barely covered, at 20C or more: it sulks below 10C, so do not put it outside before June and even then keep it out of a cold wind. Pinch the tips out as it grows to keep it bushy, and sow a second pot in July so you have young plants when the first one goes woody.\"]},{\"$tuple\":[{\"$tuple\":[\"parsley\",\"coriander\",\"cilantro\",\"dill\",\"chervil\",\"tarragon\",\"sage\"]},\"Sow parsley, coriander and dill from March to July, 1cm deep, in a pot rather than a seedbed if you only want a windowsill's worth. Parsley is slow - two to three weeks - so keep the pot damp and be patient; coriander bolts in heat, so sow it little and often and pick the leaves young. Tarragon and sage are better bought as a plant.\"]},{\"$tuple\":[{\"$tuple\":[\"mint\",\"mint plant\",\"mint plants\",\"mint root\",\"mint roots\"]},\"Mint is not grown from seed: buy a plant, or pull up a piece of root with shoots on it in spring or autumn and pot it in fresh compost. Stand it in a pot with the rim above the soil, because a mint in a border takes over, and divide the pot every couple of years when the stems get thin.\"]},{\"$tuple\":[{\"$tuple\":[\"rosemary\",\"thyme\",\"oregano\",\"oregano plant\",\"lavender\"]},\"Rosemary, thyme and oregano are bought as small plants or grown from softwood cuttings in summer, not from seed: seed is slow and comes up uneven. They want sun, very free drainage - grit in the compost, or a gravel mulch - and far less water than basil; a woody herb in wet soil rots at the base.\"]}]}")?;
