let __v_502 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"spring onion\",\"spring onions\"]},\"Spring onions are 8 to 10 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"sweetcorn\",\"sweet corn\"]},\"Sweetcorn is 12 to 14 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"runner bean\",\"runner beans\"]},\"Runner beans are 12 to 14 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"broad bean\",\"broad beans\"]},\"Broad beans are 12 to 16 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"french bean\",\"french beans\",\"dwarf bean\",\"dwarf beans\"]},\"French and dwarf beans are 10 to 12 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"salad leaves\",\"salad leaf\",\"salad\"]},\"Salad leaves are 4 to 6 weeks from seed, and you pick the outer leaves as you go.\"]},{\"$tuple\":[{\"$tuple\":[\"potato\",\"potatoes\",\"spud\",\"spuds\",\"tattie\",\"tatties\"]},\"Potatoes are 10 to 12 weeks from planting for earlies and 18 to 20 for maincrop.\"]},{\"$tuple\":[{\"$tuple\":[\"carrot\",\"carrots\"]},\"Carrots are 12 to 16 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"parsnip\",\"parsnips\"]},\"Parsnips are 22 to 24 weeks from seed, so they are most of a season.\"]},{\"$tuple\":[{\"$tuple\":[\"beetroot\"]},\"Beetroot is 10 to 12 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"radish\",\"radishes\"]},\"Radishes are 4 to 6 weeks from seed, the quickest crop there is.\"]},{\"$tuple\":[{\"$tuple\":[\"lettuce\",\"lettuces\"]},\"Lettuce is 8 to 12 weeks from seed, and the cut-and-come-again leaves are 4 to 6.\"]},{\"$tuple\":[{\"$tuple\":[\"spinach\"]},\"Spinach is 6 to 10 weeks from seed, and it bolts in the heat of summer.\"]},{\"$tuple\":[{\"$tuple\":[\"kale\"]},\"Kale takes 10 to 12 weeks before the first pickings.\"]},{\"$tuple\":[{\"$tuple\":[\"broccoli\"]},\"Broccoli is 16 to 20 weeks from seed; sprouting broccoli takes a year.\"]},{\"$tuple\":[{\"$tuple\":[\"cauliflower\",\"cauliflowers\"]},\"Cauliflower is 16 to 20 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"cabbage\",\"cabbages\"]},\"Cabbages are 16 to 20 weeks from seed, depending on the sort.\"]},{\"$tuple\":[{\"$tuple\":[\"sprouts\",\"brussels\",\"brussel\"]},\"Brussels sprouts are 20 to 24 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"swede\"]},\"Swede is 20 to 24 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"turnip\",\"turnips\"]},\"Turnips are 6 to 8 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"courgette\",\"courgettes\",\"marrow\",\"marrows\"]},\"Courgettes are 10 to 12 weeks from seed, and then they do not stop.\"]},{\"$tuple\":[{\"$tuple\":[\"pumpkin\",\"pumpkins\",\"squash\"]},\"Pumpkins are 16 to 20 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"cucumber\",\"cucumbers\"]},\"Cucumbers are 8 to 12 weeks from seed under cover.\"]},{\"$tuple\":[{\"$tuple\":[\"tomato\",\"tomatoes\"]},\"Tomatoes are 16 to 20 weeks from seed, or 12 to 16 from planting out.\"]},{\"$tuple\":[{\"$tuple\":[\"chilli\",\"chillies\",\"chili\",\"chilis\"]},\"Chillies are 16 to 20 weeks from seed, and they want warmth all of that time.\"]},{\"$tuple\":[{\"$tuple\":[\"aubergine\",\"aubergines\"]},\"Aubergines are 16 to 20 weeks, and want a warm summer.\"]},{\"$tuple\":[{\"$tuple\":[\"pepper\",\"peppers\"]},\"Peppers are 16 to 20 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"pea\",\"peas\",\"mangetout\"]},\"Peas are 12 to 14 weeks from seed.\"]},{\"$tuple\":[{\"$tuple\":[\"bean\",\"beans\"]},\"Beans are 10 to 16 weeks from seed, the dwarf sorts quickest.\"]},{\"$tuple\":[{\"$tuple\":[\"garlic\"]},\"Garlic is about eight months from an autumn clove: plant in October and lift in July.\"]},{\"$tuple\":[{\"$tuple\":[\"strawberry\",\"strawberries\"]},\"Strawberries fruit the summer after planting, so about a year from a new plant.\"]},{\"$tuple\":[{\"$tuple\":[\"onion\",\"onions\",\"leek\",\"leeks\",\"shallot\",\"shallots\"]},\"Onions and leeks are 20 to 24 weeks from seed, or about 20 weeks from sets.\"]}]}")?;
