let __v_628 = Value::from("Prune apples and pears in January or February while they are dormant: dead, diseased and crossing branches out first, then the oldest third of the stems, and the middle kept open.");
frame.store("PRUNE_APPLE", __v_628.clone())?;
let __v_629 = Value::from("Prune plums, cherries and damsons in June, not in winter: silver leaf gets in through a winter cut and kills a branch a year later. Cut back to a growing shoot and leave the pruning cuts open to the air rather than painting them.");
frame.store("PRUNE_STONE", __v_629.clone())?;
