let __v_4417 = Value::from("The garden in winter is mostly tidying and waiting: clear the dead stems but leave seed heads and any hollow stalks standing, because insects shelter in them and the birds eat the seeds. Mulch bare soil with compost or bark, but only once the ground is not frozen, and stay off wet or frozen grass because footprints kill the blades under them. Prune apples and pears and any shrub that flowers on this year's wood, clean and sharpen the tools, and wash out the greenhouse with a mild disinfectant before spring sowing. Pots are what the cold kills, so move them against a wall, raise them onto feet so the drainage hole does not sit in water, and give tender plants a layer of bubble wrap. Check the stored produce and the dahlias every couple of weeks for rot, and order seeds in January, because the quiet months are the only time the garden has nothing urgent in it.");
frame.store("_JOBS_IN_WINTER", __v_4417.clone())?;
let __v_4418 = { let __dict_4419 = Value::dict(); let __v_4420 = Value::from("spring"); let __v_4421 = Value::from("Spring goes in this order: rake the lawn and fork the beds once the soil has dried out enough not to clod, mulch the borders with compost before the weeds start, and prune the shrubs that flower on the wood they made last year - roses, buddleia, fuchsia - while they are still dormant. Sow the hardy veg outdoors, harden off anything you raised indoors for a week before it goes out, and feed the lawn once the grass is growing. Then watch the forecast, because a late frost is what takes the blossom and the new leaves, and a sheet of fleece over a flowering fruit tree earns its keep."); __dict_4419.dict_set(__v_4420, __v_4421)?; let __v_4422 = Value::from("summer"); let __v_4423 = Value::from("Summer is watering, feeding and picking: soak the beds in the evening rather than sprinkling them every day, mulch while the soil is damp to hold that water in, and water the things you planted this year first, because their roots are still shallow. Deadhead the flowers so they keep coming, feed anything in a pot every week or so, and cut the lawn a little higher rather than scalping it, which browns it in a dry spell. Pick courgettes, beans and salad small, because a plant left to swell stops making more, and get the weeds out before they set seed."); __dict_4419.dict_set(__v_4422, __v_4423)?; let __v_4424 = Value::from("autumn"); let __v_4425 = Value::from("Autumn is clearing and planting: pull the spent crops and annuals into the compost, plant bulbs and bare-root roses, fruit trees and hedging while the soil is still warm, and rake the leaves off the lawn and out of the pond. Cut back what has finished but leave the seed heads standing for the birds, mulch the beds, and give the lawn a late cut with an autumn feed rather than a short one. Then check what is stored - apples, onions, dahlias - for rot, and order next year's seed and bare-root plants, because the good varieties go early."); __dict_4419.dict_set(__v_4424, __v_4425)?; let __v_4426 = Value::from("winter"); let __v_4427 = frame.load(rt, "_JOBS_IN_WINTER")?; __dict_4419.dict_set(__v_4426, __v_4427)?; __dict_4419 };
